pm.test('Cover upload succeeds', function () {
  pm.response.to.have.status(200);
  pm.expect(response.cover_url).to.be.a('string');
});

const apiBaseUrl =
  pm.variables.get('baseUrl') || 'http://localhost:3001/api/v1';
const origin = apiBaseUrl.replace(/\/api\/v1\/?$/, '');

pm.collectionVariables.set('coverUrl', `${origin}${response.cover_url}`);

pm.test('Invalid token is rejected', function () {
  pm.response.to.have.status(401);
  pm.expect(pm.response.json().error.code).to.eql('INVALID_TOKEN');
});

